async function smeltTwoRawIron(bot) {
  const targetCount = 2;

  // 1) Ensure we have 2 raw_iron
  let rawIronCount = bot.inventory.items().filter(i => i.name === "raw_iron").reduce((s, i) => s + i.count, 0);
  if (rawIronCount < targetCount) {
    bot.chat(`Not enough raw_iron (${rawIronCount}/${targetCount}). Mining iron ore...`);
    const pickaxeNames = ["stone_pickaxe", "iron_pickaxe", "diamond_pickaxe", "netherite_pickaxe"];
    const hasPickaxe = bot.inventory.items().some(i => pickaxeNames.includes(i.name));
    if (!hasPickaxe) {
      bot.chat("No suitable pickaxe available. Cannot mine iron ore.");
      return;
    }
    let attempts = 0;
    while (rawIronCount < targetCount && attempts < 10) {
      attempts++;
      let ironBlock = bot.findBlock({
        matching: mcData.blocksByName["iron_ore"].id,
        maxDistance: 32
      });
      if (!ironBlock) {
        const directions = [new Vec3(0, -1, 0), new Vec3(1, -1, 0), new Vec3(-1, -1, 0), new Vec3(0, -1, 1), new Vec3(0, -1, -1)];
        const dir = directions[Math.floor(Math.random() * directions.length)];
        ironBlock = await exploreUntil(bot, dir, 60, () => bot.findBlock({
          matching: mcData.blocksByName["iron_ore"].id,
          maxDistance: 32
        }));
      }
      if (!ironBlock) {
        bot.chat("Failed to find iron ore.");
        break;
      }
      await mineBlock(bot, "iron_ore", targetCount - rawIronCount);
      rawIronCount = bot.inventory.items().filter(i => i.name === "raw_iron").reduce((s, i) => s + i.count, 0);
    }
    if (rawIronCount < targetCount) {
      bot.chat(`Still not enough raw_iron (${rawIronCount}/${targetCount}).`);
      return;
    }
  }
  bot.chat(`Have ${rawIronCount} raw_iron, smelting ${targetCount}.`);

  // 2) Determine a reliable fuel FIRST (prefer existing coal/charcoal)
  const plankNames = ["oak_planks", "birch_planks", "spruce_planks", "jungle_planks", "acacia_planks", "dark_oak_planks", "mangrove_planks", "cherry_planks", "bamboo_planks", "crimson_planks", "warped_planks"];
  const logNames = ["oak_log", "birch_log", "spruce_log", "jungle_log", "acacia_log", "dark_oak_log", "mangrove_log", "cherry_log"];
  function findFuel() {
    const invNames = new Set(bot.inventory.items().map(i => i.name));
    if (invNames.has("coal")) return "coal";
    if (invNames.has("charcoal")) return "charcoal";
    for (const n of plankNames) if (invNames.has(n)) return n;
    for (const n of logNames) if (invNames.has(n)) return n;
    return null;
  }
  let fuelName = findFuel();

  // If no good fuel, mine coal_ore
  if (!fuelName) {
    bot.chat("No good fuel found. Looking for coal ore...");
    let coalBlock = bot.findBlock({
      matching: mcData.blocksByName["coal_ore"].id,
      maxDistance: 32
    });
    if (!coalBlock) {
      const directions = [new Vec3(0, -1, 0), new Vec3(1, 0, 0), new Vec3(-1, 0, 0), new Vec3(0, 0, 1), new Vec3(0, 0, -1)];
      const dir = directions[Math.floor(Math.random() * directions.length)];
      coalBlock = await exploreUntil(bot, dir, 60, () => bot.findBlock({
        matching: mcData.blocksByName["coal_ore"].id,
        maxDistance: 32
      }));
    }
    if (coalBlock) {
      bot.chat("Found coal ore, mining...");
      await mineBlock(bot, "coal_ore", 1);
      fuelName = findFuel();
    }
  }

  // If still no fuel, get a log and craft planks
  if (!fuelName) {
    bot.chat("No coal found. Looking for a log to make planks...");
    let logBlock = bot.findBlock({
      matching: b => logNames.includes(b.name),
      maxDistance: 32
    });
    if (!logBlock) {
      const directions = [new Vec3(1, 0, 0), new Vec3(-1, 0, 0), new Vec3(0, 0, 1), new Vec3(0, 0, -1)];
      const dir = directions[Math.floor(Math.random() * directions.length)];
      logBlock = await exploreUntil(bot, dir, 60, () => bot.findBlock({
        matching: b => logNames.includes(b.name),
        maxDistance: 32
      }));
    }
    if (logBlock) {
      bot.chat(`Mining ${logBlock.name}...`);
      await mineBlock(bot, logBlock.name, 1);
      const plankName = logBlock.name.replace("_log", "_planks");
      await craftItem(bot, plankName, 1);
      fuelName = findFuel();
    }
  }
  if (!fuelName) {
    bot.chat("Could not obtain any valid fuel. Cannot smelt.");
    return;
  }

  // 3) Ensure a furnace is nearby; otherwise place one from inventory
  let furnaceBlock = bot.findBlock({
    matching: mcData.blocksByName.furnace.id,
    maxDistance: 32
  });
  if (!furnaceBlock) {
    const furnaceItem = bot.inventory.findInventoryItem(mcData.itemsByName["furnace"].id);
    if (!furnaceItem) {
      bot.chat("No furnace item in inventory and no furnace nearby. Cannot smelt.");
      return;
    }
    bot.chat("Placing furnace...");
    const offsets = [new Vec3(1, 0, 0), new Vec3(-1, 0, 0), new Vec3(0, 0, 1), new Vec3(0, 0, -1), new Vec3(1, 0, 1), new Vec3(-1, 0, -1)];
    for (const off of offsets) {
      const pos = bot.entity.position.offset(off.x, off.y, off.z).floored();
      try {
        await placeItem(bot, "furnace", pos);
      } catch (e) {
        continue;
      }
      furnaceBlock = bot.findBlock({
        matching: mcData.blocksByName.furnace.id,
        maxDistance: 32
      });
      if (furnaceBlock) break;
    }
    if (!furnaceBlock) {
      bot.chat("Failed to place furnace.");
      return;
    }
  }

  // 4) Free inventory space right before smelting so output can be collected
  let invSlots = bot.inventory.items().length;
  if (invSlots >= 34) {
    bot.chat("Inventory nearly full, dropping surplus items...");
    const dropList = ["cobblestone", "andesite", "granite", "diorite", "copper_ingot", "magma_block", "bone", "spider_eye", "gunpowder", "wheat_seeds", "jungle_sapling", "arrow", "torch", "dirt", "gravel", "sand"];
    for (const name of dropList) {
      if (bot.inventory.items().length < 32) break;
      const item = bot.inventory.findInventoryItem(mcData.itemsByName[name].id);
      if (item) {
        try {
          await bot.toss(item.type, null, item.count);
          bot.chat(`Dropped ${item.count} ${name}.`);
        } catch (e) {
          bot.chat(`Failed to drop ${name}: ${e.message}`);
        }
      }
    }
    invSlots = bot.inventory.items().length;
    bot.chat(`Inventory now has ${invSlots} slots used.`);
  }

  // 5) Re-verify fuel is still in inventory right before smelting
  const fuelItem = bot.inventory.findInventoryItem(mcData.itemsByName[fuelName].id);
  if (!fuelItem) {
    bot.chat(`Fuel ${fuelName} disappeared from inventory. Aborting.`);
    return;
  }

  // 6) Smelt the raw iron
  bot.chat(`Smelting ${targetCount} raw_iron using ${fuelName}...`);
  await smeltItem(bot, "raw_iron", fuelName, targetCount);
  const ingotCount = bot.inventory.items().filter(i => i.name === "iron_ingot").reduce((s, i) => s + i.count, 0);
  bot.chat(`Done. Total iron_ingot: ${ingotCount}.`);
}

