  const junkNames = ["cobblestone", "cobbled_deepslate", "andesite", "diorite", "granite", "gravel", "dirt", "sand", "tuff", "deepslate", "stone", "netherrack", "basalt", "blackstone", "calcite", "smooth_basalt"];
