      bot.chat("Mined ore but no diamond collected yet, retrying...");
    }
  }

  // 4) Verify
  if (mined) {
    bot.chat(`Done. Total diamonds in inventory: ${countDiamonds()}.`);
  } else {
    bot.chat("Failed to obtain a diamond from deepslate diamond ore after exploring.");
  }
}

